function bytes(s){return Array.from(unescape(encodeURIComponent(s)),c=>c.charCodeAt(0));}
function hex(a){return a.map(x=>(x>>>0).toString(16).padStart(8,'0')).join('');}
function padded(b){b=b.slice();const n=b.length*8;b.push(128);while(b.length%64!==56)b.push(0);const hi=Math.floor(n/4294967296),lo=n>>>0;for(const v of [hi,lo])for(let j=3;j>=0;j--)b.push((v>>>(j*8))&255);return b;}
function rol(x,n){return(x<<n)|(x>>>(32-n));}
function sha1B(input){const b=padded(input);let h=[0x67452301,0xefcdab89,0x98badcfe,0x10325476,0xc3d2e1f0];for(let o=0;o<b.length;o+=64){const w=[];for(let j=0;j<16;j++)w[j]=(b[o+j*4]<<24)|(b[o+j*4+1]<<16)|(b[o+j*4+2]<<8)|b[o+j*4+3];for(let j=16;j<80;j++)w[j]=rol(w[j-3]^w[j-8]^w[j-14]^w[j-16],1);let[a,c,d,e,f]=h;for(let j=0;j<80;j++){let z,k;if(j<20){z=(c&d)|(~c&e);k=0x5a827999;}else if(j<40){z=c^d^e;k=0x6ed9eba1;}else if(j<60){z=(c&d)|(c&e)|(d&e);k=0x8f1bbcdc;}else{z=c^d^e;k=0xca62c1d6;}const t=(rol(a,5)+z+f+k+w[j])|0;f=e;e=d;d=rol(c,30);c=a;a=t;}h=h.map((v,j)=>(v+[a,c,d,e,f][j])|0);}return hex(h);}
function sha256B(input){const ps=[];for(let x=2;ps.length<64;x++){let ok=true;for(let y=2;y*y<=x;y++)if(x%y===0){ok=false;break;}if(ok)ps.push(x);}const K=ps.map(p=>(Math.pow(p,1/3)%1*4294967296)|0);let H=ps.slice(0,8).map(p=>(Math.sqrt(p)%1*4294967296)|0);const b=padded(input),rr=(x,n)=>(x>>>n)|(x<<(32-n));for(let o=0;o<b.length;o+=64){const w=[];for(let j=0;j<16;j++)w[j]=(b[o+j*4]<<24)|(b[o+j*4+1]<<16)|(b[o+j*4+2]<<8)|b[o+j*4+3];for(let j=16;j<64;j++){const a=w[j-15],z=w[j-2];w[j]=(w[j-16]+(rr(a,7)^rr(a,18)^(a>>>3))+w[j-7]+(rr(z,17)^rr(z,19)^(z>>>10)))|0;}let[a,c,d,e,f,g,h,i]=H;for(let j=0;j<64;j++){const t1=(i+(rr(f,6)^rr(f,11)^rr(f,25))+((f&g)^(~f&h))+K[j]+w[j])|0;const t2=((rr(a,2)^rr(a,13)^rr(a,22))+((a&c)^(a&d)^(c&d)))|0;i=h;h=g;g=f;f=(e+t1)|0;e=d;d=c;c=a;a=(t1+t2)|0;}H=H.map((v,j)=>(v+[a,c,d,e,f,g,h,i][j])|0);}return hex(H);}
function info(s){const b=bytes(s);return{bytes:b.length,sha256:sha256B(b),git_blob:sha1B(bytes('blob '+b.length+'\0').concat(b))};}
return {bytes,sha1B,sha256B,info};

